> x1 <- rnorm(100)
> x2 <- rnorm(100)

> z <- 1 + 2*x1 + 3*x2 + 0.1 * rt(100, 7)
> pr <- 1/(1+exp(-z))
> y <- rbinom(100,10,pr)
>
> df <- list(N=100, y=y, x1=x1, x2=x2, nu = 7)

>
> # Stan code
> model1 <- '
> data {
>    int<lower=0> N;

>    int<lower=0,upper=10> y[N];

>    vector[N] x1;
>    vector[N] x2;

       real nu;

> }
> parameters {
>    real beta_0;
>    real beta_1;
>    real beta_2;

      real<lower=0> sigma_e;
      vector[N] e;
> }
> model {
      e ~ student_t(nu, 0, sigma_e);
      sigma_e ~ cauchy(0, 1);
>    y ~ binomial_logit(10, beta_0 + beta_1 * x1 + beta_2 * x2 + e);
> }
> '
> # Run the model
> fit <- stan(model_code = model1, data = df, iter = 4000, chains = 2)
> print(fit)

There's also a discussion of robit in the regression chapter
of the manual.

And yes, you can do the same thing in a hierarchical setting,
but you have to be careful because modeling the degrees of freedom
can be tricky given the scale runs off to infinity as you approach
normality.

- Bob

